"""PaperCI web app: authors submit a paper (arXiv link or PDF + code repo), the agent verifies the claims in
a fresh sandbox, and the author follows it live and gets a private review link.

    python -m paperci.web            # http://127.0.0.1:8000  (binds localhost only)

One verification runs at a time (each costs real model spend and a sandbox). Jobs are processed by
`python -m paperci review ...` subprocesses so a crash never takes the web server down."""
from __future__ import annotations

import html
import json
import os
import re
import secrets
import subprocess
import sys
import threading
import time
from pathlib import Path

from fastapi import FastAPI, File, Form, HTTPException, UploadFile
from fastapi.responses import FileResponse, HTMLResponse, JSONResponse, RedirectResponse
from fastapi.staticfiles import StaticFiles

from . import db, ledger, sources
from .config import REGISTRY_DIR, ROOT

WEB = REGISTRY_DIR / "web"
JOBS = WEB / "jobs"
OUTBOX = WEB / "outbox"
UPLOADS = WEB / "uploads"
for d in (JOBS, OUTBOX, UPLOADS):
    d.mkdir(parents=True, exist_ok=True)
BASE_URL = os.environ.get("PAPERCI_WEB_URL", "http://127.0.0.1:8000")
MAX_PDF = 25 * 1024 * 1024
ANSI = re.compile(r"\x1b\[[0-9;]*m")
EMAIL = re.compile(r"^[^@\s]{1,64}@[^@\s]{1,190}\.[A-Za-z]{2,24}$")

db.ex("""CREATE TABLE IF NOT EXISTS web_jobs (token TEXT PRIMARY KEY, email TEXT, kind TEXT, input TEXT, repo TEXT,
         paper_id TEXT, title TEXT, label TEXT, status TEXT, created REAL, started REAL, finished REAL,
         review_path TEXT, error TEXT)""")

STEPS = [  # (ui name, explanation, pipeline stage titles that drive it)
    ("Read the paper", "Fetch the paper and find its code", ["Fetch paper metadata", "Snapshot repository metadata"]),
    ("Check it can run here", "CPU sandbox, no GPU, no API keys", ["Triage"]),
    ("Seal the claims", "Headline numbers extracted with quotes, hashed, hidden from the agent", ["Extract and seal"]),
    ("Rebuild the environment", "Agent installs deps and gets your code running in a fresh container", ["Builder agent"]),
    ("Verify with the network off", "A different model family reruns it in a new container", ["Independent verifier"]),
    ("Rerun with other seeds", "Calibrates a tolerance from the spread", ["Robustness"]),
    ("Compare claims vs measured", "Plus anti-cheat integrity checks", ["Verdict"]),
    ("Package a reproducible task", "Script, environment and hidden test", ["Package as"]),
    ("Replay in a clean environment", "The package must reproduce itself", ["Oracle"]),
]
HOSTS = {"codeload.github.com": "GitHub", "github.com": "GitHub", "api.github.com": "GitHub API",
         "objects.githubusercontent.com": "GitHub releases", "pypi.org": "PyPI", "files.pythonhosted.org": "PyPI",
         "download.pytorch.org": "PyTorch wheels", "huggingface.co": "Hugging Face", "cdn-lfs.huggingface.co": "Hugging Face",
         "zenodo.org": "Zenodo", "www.openml.org": "OpenML", "archive.ics.uci.edu": "UCI datasets"}


# ---------------- job runner ----------------
def _job(token: str) -> dict | None:
    r = db.q1("SELECT * FROM web_jobs WHERE token=?", (token,))
    return dict(r) if r else None


def _set(token: str, **kw) -> None:
    db.ex(f"UPDATE web_jobs SET {','.join(k + '=?' for k in kw)} WHERE token=?", (*kw.values(), token))


def _send_email(job: dict) -> None:
    """Email delivery is not wired to a mail provider in this build: the message is written to the outbox."""
    link = f"{BASE_URL}/job/{job['token']}"
    body = (f"To: {job['email']}\nFrom: PaperCI <[REDACTED_EMAIL]>\nSubject: Your PaperCI review is ready: "
            f"{job['title'] or job['input']}\n\nHi,\n\nPaperCI finished verifying the claims of your paper.\n"
            f"Your private review: {link}\n\nThe review lists every headline claim, what your released code produced "
            f"in a fresh sandbox, and concrete suggestions.\n\n- PaperCI\n")
    (OUTBOX / f"{job['token']}.eml").write_text(body, encoding="utf-8")


def _run(job: dict) -> None:
    log = JOBS / f"{job['token']}.log"
    cmd = [sys.executable, "-u", "-m", "paperci", "review", "--label", job["label"]]
    if job["kind"] == "pdf":
        cmd += ["--pdf", job["input"]]
        if job["repo"]:
            cmd += ["--repo", job["repo"]]
    else:
        cmd += [job["input"]] + (["--repo", job["repo"]] if job["repo"] else [])
    env = {**os.environ, "PYTHONIOENCODING": "utf-8", "PAPERCI_LIVE": "1"}
    _set(job["token"], status="running", started=time.time())
    with open(log, "w", encoding="utf-8") as f:
        p = subprocess.run(cmd, cwd=ROOT, stdout=f, stderr=subprocess.STDOUT, env=env)
    text = log.read_text(encoding="utf-8", errors="replace")
    m = re.findall(r"REVIEW_PATH: (.+)", text)
    if p.returncode == 0 and m:
        _set(job["token"], status="done", finished=time.time(), review_path=m[-1].strip())
        _send_email(_job(job["token"]))
    else:
        err = next((ANSI.sub("", l) for l in reversed(text.splitlines()) if l.strip() and " - neatlogs - " not in l), "failed")
        _set(job["token"], status="failed", finished=time.time(), error=err[-300:])


def _worker() -> None:
    while True:
        try:
            row = db.q1("SELECT * FROM web_jobs WHERE status='queued' ORDER BY created LIMIT 1")
            if row:
                _run(dict(row))
                continue
        except Exception as e:  # keep the worker alive; the job shows the error
            if row:
                _set(row["token"], status="failed", error=str(e)[:300], finished=time.time())
        time.sleep(2)


# ---------------- progress parsing ----------------
def _progress(job: dict) -> dict:
    log = JOBS / f"{job['token']}.log"
    raw = log.read_text(encoding="utf-8", errors="replace") if log.exists() else ""
    lines = [ANSI.sub("", l) for l in raw.splitlines() if " - neatlogs - " not in l and l.strip()]
    state = {s[0]: "todo" for s in STEPS}
    detail: dict[str, str] = {}
    feed, claims = [], None
    for l in lines:
        m = re.match(r"^(\d\d:\d\d) (\s*)([>+x!~.=]) (.*)$", l)
        if not m:
            continue
        ts, ind, g, txt = m.groups()
        if ind:
            feed.append({"t": ts, "g": g, "text": txt.strip()})
            continue
        for name, _, keys in STEPS:
            if any(txt.startswith(k) for k in keys):
                if g == ">":
                    state[name] = "run"
                elif g in "+=":
                    state[name] = "ok"
                    if "->" in txt:
                        detail[name] = txt.split("->", 1)[1].strip()
                elif g == "x":
                    state[name] = "fail"
        if g == "!" and txt.startswith("stopping"):
            feed.append({"t": ts, "g": g, "text": txt})
        mc = re.search(r"(\d+) claims sealed", txt)
        if mc:
            claims = int(mc.group(1))
    if job["status"] in ("done", "failed"):
        for k, v in state.items():
            if v == "run":
                state[k] = "fail" if job["status"] == "failed" else "ok"
    if detail.get("Check it can run here", "").startswith("reject"):
        state["Check it can run here"] = "fail"
    if "built" not in detail.get("Rebuild the environment", "built") and state["Rebuild the environment"] == "ok":
        state["Rebuild the environment"] = "fail"
    conns = _connections(job, raw)
    return {"status": job["status"], "title": job["title"], "steps": [
        {"name": n, "why": w, "state": state[n], "detail": detail.get(n, "")} for n, w, _ in STEPS],
        "feed": feed[-60:], "claims_sealed": claims, "connections": conns,
        "elapsed": int((job["finished"] or time.time()) - (job["started"] or job["created"])),
        "queued_ahead": db.q1("SELECT COUNT(*) n FROM web_jobs WHERE status IN ('queued','running') AND created<?",
                              (job["created"],))["n"] if job["status"] == "queued" else 0,
        "review": f"/job/{job['token']}/review" if job["status"] == "done" else None, "error": job["error"],
        "email_saved": (OUTBOX / f"{job['token']}.eml").exists()}


def _connections(job: dict, raw: str) -> list[dict]:
    out: dict[str, str] = {}
    if job["kind"] == "arxiv":
        out["arXiv"] = "ok"
    if "fetched " in raw:
        out["GitHub"] = "ok"
    if re.search(r"pip3? install[^\n]*-> exit 0", raw):
        out["PyPI"] = "ok"
    if job["paper_id"]:
        row = db.q1("SELECT output FROM stages WHERE arxiv_id=? AND stage='build' AND run_label=? AND status='done'",
                    (job["paper_id"], job["label"]))
        if row:
            eg = (json.loads(row["output"]).get("egress") or {})
            for h in eg.get("allowed", {}):
                out[HOSTS.get(h, h)] = "ok"
            for h in eg.get("denied", {}):
                out[HOSTS.get(h, h)] = "blocked"
    if "--network none" in raw:
        out["Verification: network OFF"] = "off"
    return [{"host": k, "state": v} for k, v in out.items()]


# ---------------- pages ----------------
CSS = """
*{box-sizing:border-box}body{margin:0;font:15px/1.6 Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Helvetica,Arial,sans-serif;color:#0f172a;background:#fff}
a{color:#4f46e5}.nav{display:flex;align-items:center;justify-content:space-between;max-width:1120px;margin:0 auto;padding:18px 24px}
.logo{font-weight:800;font-size:20px;letter-spacing:-.02em;color:#0f172a;text-decoration:none}.logo span{color:#4f46e5}
