    s = {k: state.get(k) for k in STATE_KEYS}
    s["actions"] = [{k: a.get(k) for k in ACTION_KEYS if k in a} for a in state.get("actions", [])]
    s["fired"] = list(state.get("fired", []))
    s["failures"] = list(state.get("failures", []))
    return s


