            c["screen"] = {"status": "error", "why": f"{type(ex).__name__}: {str(ex)[:160]}"}
        _save(CANDS, cands)
    _assign_roles(cands)
    _save(CANDS, cands)
    return dict(collections.Counter((c.get("screen") or {}).get("status", "unscreened") for c in cands))

