def learning_evidence(labels: list[str], bench: list[str]) -> dict:
    """Failures the improver may learn from: dev papers, live autopilot papers and the benchmark papers. Never
    held-out papers and never ICML eval papers, so both scores stay blind."""
    out: dict[str, list[dict]] = {}
    for split in ("dev", "live"):
        for k, xs in _evidence(labels, only_split=split).items():
