        flags.append("prebuilt_result_files")
    script = (build_dir / "paperci_run.sh").read_text(encoding="utf-8", errors="replace") if (build_dir / "paperci_run.sh").exists() else ""
    ok_runs = [r for r in runs if r.get("exit_code") == 0]
