"""Spend ledger: tokens x price per call, per-paper caps and a global stop."""
from __future__ import annotations

import os
import time

import requests

from . import db
from .config import (DEMO_RESERVE_USD, GLOBAL_BUDGET_USD, HARD_STOP_USD, LITELLM_BASE_URL,
                     PER_PAPER_CAP_USD, PRICES)


class BudgetExceeded(RuntimeError):
    """Raised before a call that would cross a budget line."""


_remote_cache: dict[str, float] = {"ts": 0.0, "spend": 0.0}


def price_call(model: str, prompt_tokens: int, completion_tokens: int,
               cache_read: int = 0, cache_write: int = 0) -> float:
    # Unknown models are priced as the most expensive allowed model (conservative).
    p = PRICES.get(model) or PRICES["claude-sonnet-4.6"]
    uncached = max(prompt_tokens - cache_read - cache_write, 0)
    return (uncached * p["in"] + completion_tokens * p["out"]
            + cache_read * p.get("cache_read", p["in"]) + cache_write * p.get("cache_write", p["in"]))


def record(arxiv_id: str, stage: str, run_label: str, model: str, prompt_tokens: int,
           completion_tokens: int, cache_read: int = 0, cache_write: int = 0) -> float:
    cost = price_call(model, prompt_tokens, completion_tokens, cache_read, cache_write)
    db.ex("INSERT INTO spend (ts,arxiv_id,stage,run_label,model,prompt_tokens,completion_tokens,"
          "cache_read_tokens,cache_write_tokens,cost_usd) VALUES (?,?,?,?,?,?,?,?,?,?)",
          (time.time(), arxiv_id, stage, run_label, model, prompt_tokens, completion_tokens,
           cache_read, cache_write, cost))
    return cost


def local_total() -> float:
    r = db.q1("SELECT COALESCE(SUM(cost_usd),0) AS s FROM spend")
    return float(r["s"]) if r else 0.0


def paper_total(arxiv_id: str, run_label: str | None = None, stage: str | None = None) -> float:
    sql, args = "SELECT COALESCE(SUM(cost_usd),0) AS s FROM spend WHERE arxiv_id=?", [arxiv_id]
    if run_label:
        sql += " AND run_label=?"; args.append(run_label)
    if stage:
        sql += " AND stage=?"; args.append(stage)
    r = db.q1(sql, tuple(args))
    return float(r["s"]) if r else 0.0


def remote_spend(max_age: float = 300.0) -> float:
    """Authoritative spend reported by the LiteLLM proxy for this key."""
    if time.time() - _remote_cache["ts"] < max_age:
        return _remote_cache["spend"]
    base = LITELLM_BASE_URL.rstrip("/")
    base = base[:-3] if base.endswith("/v1") else base
    try:
        r = requests.get(f"{base}/key/info", timeout=15,
                         headers={"Authorization": "Bearer " + os.environ["LITELLM_API_KEY"]})
        r.raise_for_status()
        _remote_cache.update(ts=time.time(), spend=float(r.json()["info"].get("spend") or 0.0))
    except Exception:
        _remote_cache["ts"] = time.time()
    return _remote_cache["spend"]


def global_spend() -> float:
    return max(local_total(), remote_spend())


def today_total() -> float:
    """Local spend since midnight in the operator's timezone (PAPERCI_TZ_OFFSET_H, default IST)."""
    off = float(os.getenv("PAPERCI_TZ_OFFSET_H", "5.5")) * 3600
    start = ((time.time() + off) // 86400) * 86400 - off
    start = max(start, float(os.getenv("PAPERCI_CAP_SINCE", "0")))  # deploy time: history copied in doesn't count
    # Evolution rounds have their own nightly budget, so they do not eat the autopilot's daily pacing.
    r = db.q1("SELECT COALESCE(SUM(cost_usd),0) AS s FROM spend WHERE ts>=? AND run_label NOT LIKE 'evo-%' "
              "AND run_label NOT LIKE 'icml-%'", (start,))
    return float(r["s"]) if r else 0.0


def daily_cap() -> float | None:
    v = os.getenv("PAPERCI_DAILY_CAP")
    return float(v) if v else None


def precheck(arxiv_id: str, run_label: str, est_cost: float, stage_cap: float | None = None,
             stage: str | None = None, allow_reserve: bool = False) -> None:
    spent = global_spend()
    limit = min(HARD_STOP_USD, GLOBAL_BUDGET_USD - (0 if allow_reserve else DEMO_RESERVE_USD))
    if spent + est_cost > limit:
        raise BudgetExceeded(f"global spend {spent:.3f}+{est_cost:.3f} > limit {limit:.2f}")
    cap = daily_cap()
    # The daily cap paces the autopilot across days. Author submissions are already gated by invite codes,
    # a per-IP rate limit, the web spend cap and the hard stop above, so they are not starved by it. The
    # evolution loop has its own nightly budget (paperci/evolve.py) and is exempt for the same reason.
    exempt = any(os.getenv(k) == "1" for k in ("PAPERCI_AUTHOR_JOB", "PAPERCI_EVOLVE_JOB", "PAPERCI_BUDGETED_JOB"))
    if cap is not None and not allow_reserve and not exempt:
        t = today_total()
        if t + est_cost > cap:
            raise BudgetExceeded(f"daily spend {t:.3f}+{est_cost:.3f} > daily cap {cap:.2f}")
    if arxiv_id and arxiv_id != "-":
        p = paper_total(arxiv_id, run_label)
        if p + est_cost > PER_PAPER_CAP_USD:
            raise BudgetExceeded(f"paper spend {p:.3f}+{est_cost:.3f} > cap {PER_PAPER_CAP_USD:.2f}")
        if stage_cap is not None and stage:
            s = paper_total(arxiv_id, run_label, stage)
            if s + est_cost > stage_cap:
                raise BudgetExceeded(f"stage {stage} spend {s:.3f}+{est_cost:.3f} > cap {stage_cap:.2f}")


def summary() -> dict:
    rows = db.q("SELECT stage, model, COUNT(*) n, SUM(prompt_tokens) pt, SUM(completion_tokens) ct, "
                "SUM(cost_usd) c FROM spend GROUP BY stage, model ORDER BY c DESC")
    return {"local_total": local_total(), "remote_total": remote_spend(0),
            "by_stage_model": [dict(r) for r in rows]}

    return _page("PaperCI on ICML 2026 papers", f"""<div class=wrap style='padding:20px 0 60px'>
<h1>PaperCI on ICML 2026 papers</h1>
<p>The answer key is <a href="https://huggingface.co/datasets/ICML-2026-agent-repro/verdicts" target=_blank rel=noopener>Hugging
Face's ICML 2026 Open Reproductions</a>: community teams reproduced papers claim by claim, and a GLM-5.2 judge
graded their logbooks. We kept only papers where at least two medium- or high-quality logbooks agreed (75% or more) that
the paper was verified or falsified. PaperCI runs each one blind: no agent ever sees the community verdict. Builder model:
{e(MODELS['builder'])}; verifier model: {e(MODELS['verifier'])}.</p>
<p class=muted>{e(AUTOMATED_NOTE)} The community labels come from an LLM judge, so they can be wrong too.
"No decision" means PaperCI could not build or measure the paper within its limits. "Reduced scale only" means the
code ran and was measured on a smaller setting (fewer steps, seeds or data) that fits a CPU; it is evidence that the
code works, not a verdict on the paper's full-scale numbers.</p>{head}{queue}
{''.join(cards) or "<p class=muted>The first results appear here as runs finish.</p>"}</div>""")


@app.get("/judges", response_class=HTMLResponse)
def judges_page():
    from . import judges
    return _page("PaperCI - evidence for judges", judges.render(judges.collect()))


@app.get("/judges.json")
def judges_json():
    from . import judges
    d = judges.collect()
    return JSONResponse({**d, "checks": [{k: c[k] for k in ("id", "title", "rule", "status", "verify")} for c in judges.checks(d)]})


@app.get("/icml/review")
def icml_review_redirect():
    return RedirectResponse("/icml", status_code=301)


@app.get("/icml/r/{arxiv}")
def icml_review_file(arxiv: str):
    from . import icml_eval
    runs = [r for st in (icml_eval.STATE, icml_eval.STATE_P1) for r in icml_eval._load(st, {"runs": []})["runs"]
            if r["arxiv"] == arxiv and r.get("review")]
    run = runs[0] if runs else None
    p = Path(run["review"]) if run else None
    if not p or not p.exists() or REGISTRY_DIR.resolve() not in p.resolve().parents:
        raise HTTPException(404)
    banner = (f"<div style='background:#fef3c7;border-bottom:1px solid #f59e0b;padding:10px 16px;font:14px system-ui'>"
              f"{html.escape(AUTOMATED_NOTE)} <a href='/icml'>All ICML 2026 results and the community verdicts</a></div>")
    page = p.read_text(encoding="utf-8")
    page = re.sub(r"(<body[^>]*>)", lambda m: m.group(1) + banner, page, count=1)
    return HTMLResponse(page)


@app.post("/submit")
async def submit(request: Request, email: str = Form(...), arxiv: str = Form(""), repo: str = Form(""),
                 consent: str = Form(""), invite: str = Form(""), paper: UploadFile | None = File(None)):
    email, arxiv, repo = email.strip(), arxiv.strip(), repo.strip()
    if INVITES and invite.strip() not in INVITES:
        return landing("That invite code is not valid. PaperCI is in early access; ask the team for a code.", email, arxiv, repo)
    # Behind the Vercel front door Caddy sees Vercel's edge IP; Vercel passes the visitor's IP in its own header.
    ip = (request.headers.get("x-vercel-forwarded-for") or request.headers.get("x-forwarded-for")
          or (request.client.host if request.client else "?")).split(",")[0].strip()
    recent = [t for t in SUBMITS.get(ip, []) if time.time() - t < 3600]
    if len(recent) >= SUBMITS_PER_HOUR:
        return landing("Too many submissions from your network in the last hour. Please try again later.", email, arxiv, repo)
    SUBMITS[ip] = recent + [time.time()]
    if not EMAIL.match(email):
        return landing("Please enter a valid email address.", email, arxiv, repo)
